// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILineAxis {
    function balanceOf(address owner) external view returns(uint);
    function approve(address spender, uint256 value) external returns(bool);
    function transfer(address to, uint256 value) external returns(bool);
    function allowance(address owner, address spender) external view returns(uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond what the test framework provides
        // The target contract is already deployed at TARGET
        // We'll use deal() to give attacker some tokens
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Give attacker some token balance (less than what we'll try to approve)
        uint256 attackerBalance = 1000 * 10**18; // 1000 tokens with 18 decimals
        deal(TARGET, attacker, attackerBalance);

        // Check current balance to confirm
        uint256 balanceBefore = ILineAxis(TARGET).balanceOf(attacker);
        require(balanceBefore == attackerBalance, "Balance not set correctly");

        // Try to approve an amount greater than our balance
        uint256 approvalAmount = attackerBalance + 1;

        // This should revert due to the incorrect check in approve()
        // We expect the transaction to fail
        bool success;
        bytes memory returnData;

        (success, returnData) = TARGET.call(
            abi.encodeWithSignature("approve(address,uint256)", address(0x1234), approvalAmount)
        );

        // The oracle expects success == false
        // This demonstrates the broken approve() function
        assertEq(success, false, "Approve should fail when amount > balance");

        // Check allowance to verify state wasn't changed
        uint256 allowanceAfter = ILineAxis(TARGET).allowance(attacker, address(0x1234));
        assertEq(allowanceAfter, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
